def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for c in range(w):
        if grid[h - 1][c] != 5:
            continue

        anchors = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        if not anchors:
            continue

        # Each encountered color extends upward to the previous anchor.
        start = 0
        for r, color in anchors:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1

        # Extend the final anchor down to the bottom.
        last_color = anchors[-1][1]
        for rr in range(start, h):
            out[rr][c] = last_color

    return out
